import {SERVICES,DEPARTMENTS} from './civic.js?v=civic-inspection-1';
import {occupancy} from './utilities.js?v=civic-inspection-1';
import {educationWeights} from './education.js?v=civic-inspection-1';
const CAPACITY_SERVICES=['hospital','school','college','library','museum'];
export function civicFacilityDetails(c,t){
 const definition=SERVICES[t.type];if(!definition)return null;
 const funding=c.civic.funding[definition.department],strike=c.civic.underfunded[definition.department]>=6,reasons=[];
 if(!t.powered)reasons.push('No electricity');if(!t.roadIds?.length)reasons.push('No nearby road');if(c.finance.roadCondition<=20)reasons.push('Road network closed by poor condition');if(funding===0)reasons.push('Department funding is zero');if(strike)reasons.push('Department workers are on strike');
 const homes=c.tiles.filter(h=>h.type==='residential'&&h.level&&h.roadIds.some(id=>t.roadIds.includes(id))),residents=homes.reduce((sum,h)=>sum+occupancy(h.level)*8,0),mix=educationWeights(c),weight=t.type==='school'?.65:t.type==='college'?.35:1,share=['school','college'].includes(t.type)?mix.youth:['library','museum'].includes(t.type)?mix.adult:1;
 const demand=residents*share,fundedCapacity=(definition.capacity||0)*funding/100*weight,capacity=t.serviceActive?fundedCapacity:0;
 const field=t.type==='hospital'?'healthCoverage':['school','college'].includes(t.type)?'schoolCoverage':'adultEducationCoverage',combinedCoverage=residents?homes.reduce((sum,h)=>sum+(h[field]||0)*occupancy(h.level)*8,0)/residents:0;
 return{definition,funding,strike,reasons,operating:!!t.serviceActive,monthlyCost:definition.upkeep*funding/100,capacityService:CAPACITY_SERVICES.includes(t.type),residents,homes:homes.length,demand,fundedCapacity,capacity,contribution:demand?Math.min(100,capacity/demand*100):0,combinedCoverage,group:t.type==='hospital'?'residents':['school','college'].includes(t.type)?'young residents':'adult residents',weight};
}
export function civicFacilityReport(c,t){
 const d=civicFacilityDetails(c,t);if(!d)return'';const number=n=>n.toLocaleString(undefined,{maximumFractionDigits:1});
 let body=`<p class="fine">Tile ${t.x+1}, ${t.y+1}</p><p>${d.operating?'Operating.':d.reasons.length?'Not operating: '+d.reasons.join('; ')+'.':'Not operating.'}</p><div class="metric-grid"><div><small>${DEPARTMENTS[d.definition.department]} funding</small><strong>${d.funding}%</strong></div><div><small>Monthly upkeep contribution</small><strong>§${number(d.monthlyCost)}</strong></div></div>`;
 if(d.capacityService)body+=`<h3>Road-connected service area</h3><div class="metric-grid"><div><small>Occupied homes reached</small><strong>${d.homes}</strong></div><div><small>Residents on these road networks</small><strong>${number(d.residents)}</strong></div><div><small>Demand · ${d.group}</small><strong>${number(d.demand)}</strong></div><div><small>Operating capacity contribution</small><strong>${number(d.capacity)}</strong></div><div><small>This facility’s coverage contribution</small><strong>${number(d.contribution)}%</strong></div><div><small>Combined local coverage</small><strong>${number(d.combinedCoverage)}%</strong></div></div><p>${d.residents?'This facility shares its capacity across these connected homes. Contributions can overlap other facilities; combined coverage is capped at 100% per home.':'No occupied homes share a road network with this facility. Connecting a road only at the building is not enough to reach a disconnected neighborhood.'}</p>${d.group!=='residents'?'<p>Young/adult demand is estimated from the city’s age mix, as in the education simulation. Schools contribute 65% and colleges 35% of their funded capacity toward youth learning; libraries and museums support adult retention.</p>':''}<p>${!d.operating?'Restore the missing service conditions to use its funded contribution of '+number(d.fundedCapacity)+'.':d.demand>d.capacity&&d.combinedCoverage<99.9?'This area has unmet demand. Increase department funding or add another connected facility.':d.demand?'Coverage is sufficient or shared with other facilities. Check other neighborhoods before adding capacity here.':'Zone and develop homes along a connected road network to use this capacity.'}</p>`;
 else if(t.type==='jail')body+=`<p>Citywide jail demand: ${number(c.stats.jailNeed)}. This jail contributes ${number(d.capacity)} operating places. Combined city adequacy: ${number(c.stats.jailAdequacy*100)}%.</p>`;
 else body+=`<p>Base response radius: ${d.definition.radius} tiles. At this funding level, the operating radius is ${number(d.operating?d.definition.radius*Math.sqrt(d.funding/100):0)} tiles. Coverage weakens with distance; inspect the coverage map for gaps.${t.type==='police'?' Jail adequacy also affects police effectiveness.':''}</p>`;
 return body+'<p class="fine">Department bills are rounded after adding their building contributions.</p><button id="inspectCivicDepartment">Review department funding and services</button>';
}
